#[derive(Debug, Serialize)]
struct ManagedCompletionRequest<'a> {
    model: &'a str,
    prompt: &'a str,
    stream: bool,
}

#[derive(Debug, Deserialize)]
struct ManagedCompletionChoice {
    text: String,
}

#[derive(Debug, Default, Deserialize)]
struct ManagedCompletionUsage {
    #[serde(default)]
    prompt_tokens: Option<u64>,
    #[serde(default)]
    completion_tokens: Option<u64>,
}

#[derive(Debug, Deserialize)]
struct ManagedCompletionResponse {
    #[serde(default)]
    choices: Vec<ManagedCompletionChoice>,
    #[serde(default)]
    usage: ManagedCompletionUsage,
}

struct ManagedGenerationResponse {
    text: String,
    prompt_tokens: Option<u64>,
    response_tokens: Option<u64>,
}

fn generate_managed(
    config: &ManagedModelConfig,
    prompt: &str,
    interrupted: &AtomicBool,
    active_stream: &Mutex<Option<TcpStream>>,
) -> Result<ManagedGenerationResponse, NativeAgentError> {
    let managed = ManagedLocalRuntime::ensure_endpoint(&config.config)?;
    let endpoint = LocalHttpEndpoint::parse(&managed.url).map_err(|error| {
        ManagedLocalRuntimeError::inference_protocol(error.to_string())
    })?;
    let body = serde_json::to_vec(&ManagedCompletionRequest {
        model: &config.config.model_id,
        prompt,
        stream: false,
    })
    .map_err(|error| ManagedLocalRuntimeError::inference_protocol(error.to_string()))?;
    let mut stream = endpoint.connect().map_err(|error| {
        ManagedLocalRuntimeError::inference_protocol(error.to_string())
    })?;
    if interrupted.load(Ordering::Acquire) {
        return Err(NativeAgentError::Interrupted);
    }
    if let Ok(mut guard) = active_stream.lock() {
        *guard = stream.try_clone().ok();
    }
    write!(
        stream,
        "POST /v1/completions HTTP/1.1\r\nHost: {}\r\nContent-Type: application/json\r\nAccept: application/json\r\nContent-Length: {}\r\nConnection: close\r\n\r\n",
        endpoint.host_header(),
        body.len()
    )
    .map_err(|error| ManagedLocalRuntimeError::inference_protocol(error.to_string()))?;
    stream
        .write_all(&body)
        .and_then(|()| stream.flush())
        .map_err(|error| ManagedLocalRuntimeError::inference_protocol(error.to_string()))?;
    let mut response = Vec::new();
    let read_result = stream
        .take(MAX_HTTP_RESPONSE_BYTES + 1)
        .read_to_end(&mut response);
    if let Ok(mut guard) = active_stream.lock() {
        *guard = None;
    }
    if interrupted.load(Ordering::Acquire) {
        return Err(NativeAgentError::Interrupted);
    }
    read_result
        .map_err(|error| ManagedLocalRuntimeError::inference_protocol(error.to_string()))?;
    if response.len() as u64 > MAX_HTTP_RESPONSE_BYTES {
        return Err(ManagedLocalRuntimeError::inference_protocol(
            "managed llama.cpp response exceeded the safety limit",
        )
        .into());
    }
    let parsed = parse_http_response(&response).map_err(|error| {
        ManagedLocalRuntimeError::inference_protocol(error.to_string())
    })?;
    if parsed.status != 200 {
        let message = String::from_utf8_lossy(&parsed.body);
        return Err(ManagedLocalRuntimeError::inference_protocol(format!(
            "managed llama.cpp returned HTTP {}: {}",
            parsed.status,
            truncate_text(message.trim(), 500),
        ))
        .into());
    }
    let response = serde_json::from_slice::<ManagedCompletionResponse>(&parsed.body)
        .map_err(|error| ManagedLocalRuntimeError::inference_protocol(error.to_string()))?;
    let text = response
        .choices
        .into_iter()
        .next()
        .map(|choice| choice.text.trim().to_owned())
        .filter(|text| !text.is_empty())
        .ok_or_else(|| {
            ManagedLocalRuntimeError::inference_protocol(
                "managed llama.cpp returned an empty completion",
            )
        })?;
    Ok(ManagedGenerationResponse {
        text,
        prompt_tokens: response.usage.prompt_tokens,
        response_tokens: response.usage.completion_tokens,
    })
}

